<?php declare(strict_types=1); require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth_check.php'; require_once __DIR__.'/../includes/helpers.php'; require_login(); require_post_csrf();
$name=trim((string)($_POST['category_name']??'')); if($name===''||mb_strlen($name)>100){flash('error','Nama kategori wajib diisi (maksimal 100 karakter).');redirect_to('/pages/categories.php');}
try{$s=db()->prepare('INSERT INTO categories (category_name,created_at) VALUES (?,NOW())');$s->execute([$name]);log_activity(db(),(int)$_SESSION['user_id'],'Menambahkan kategori: '.$name);flash('success','Kategori berhasil ditambahkan.');}catch(PDOException $e){error_log($e->getMessage());flash('error','Kategori tidak dapat ditambahkan.');}redirect_to('/pages/categories.php');
